struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a; sz[a] += sz[b];
        return true;
    }
};

int main() {
    int n = 5;
    vector<array<int, 2>> edges = {{0, 1}, {1, 2}, {3, 4}, {2, 0}};
    DSU d(n);
    int comps = n;
    for (auto [a, b] : edges)
        if (d.unite(a, b)) comps--;   // false: edge closes a cycle
    cout << comps << "\n";
}
